using System.Reflection;
using System.Text.Json;
using System.Text.Json.Nodes;
using GnOuGo.KeyVault.Core.Services;
using GnOuGo.Flow.Core.Planning;
using GnOuGo.Flow.Planning;
var records = KeyVaultRecordStoreFactory.CreateWorkspaceStore(null, args[0]);
var saved = await records.GetAsync("planning-schema-portability", "benchmark", "schema-portability-20261002:run:sequential20261011a-amazon-1", "GnOuGo.Planning.Benchmark") ?? throw new Exception("Missing retained record");
var state = JsonNode.Parse(saved.Value)!["session"]!.Deserialize(PlanningJsonContext.Default.PlanningSession)!;
var compileTask = typeof(TaskPlanCompiler).GetMethods(BindingFlags.NonPublic | BindingFlags.Instance).Single(m => m.Name == "Compile" && m.GetParameters().Length == 3 && m.GetParameters()[2].ParameterType == typeof(PlanningRequest));
var compiled = (TaskCompilation)compileTask.Invoke(new TaskPlanCompiler(), [state.Plan!,state.Catalog!,state.Request])!;
if(compiled.Diagnostics.Count != 0) throw new Exception(string.Join(";",compiled.Diagnostics));
var compile = typeof(PlanningGraphCompiler).GetMethods(BindingFlags.NonPublic | BindingFlags.Instance).Single(m => m.Name == "Compile" && m.GetParameters().Length == 10);
var yaml = (string)compile.Invoke(new PlanningGraphCompiler(), [compiled.Graph!,state.Catalog!,state.Request.Name,true,true,true,true,true,true,true])!;
var hash = PlanningGraphCompiler.Fingerprint(yaml);
if(hash != "86de0c717fb8ed177d5bab3ec16b1fae77ea4bb16889e49d99f469482ae3730b") throw new Exception("Historical YAML changed: " + hash);
var after = await records.GetAsync("planning-schema-portability", "benchmark", "schema-portability-20261002:run:sequential20261011a-amazon-1", "GnOuGo.Planning.Benchmark");
if(saved.Value != after!.Value) throw new Exception("Historical record changed");
Console.WriteLine(new JsonObject { ["run"]="sequential20261011a-amazon-1", ["profile"]="compact-bindings-v9", ["bytes"]=System.Text.Encoding.UTF8.GetByteCount(yaml), ["sha256"]=hash, ["provider_calls"]=0, ["mcp_calls"]=0, ["saved_record_unchanged"]=true }.ToJsonString());
